import{R as e,e as o,f as n,U as r}from"./chunks/framework.ywem4qy5.js";const d=JSON.parse('{"title":"SharpSpring","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/sharpspring.md","filePath":"integrations/crm/sharpspring.md","lastUpdated":1775908585000}'),i={name:"integrations/crm/sharpspring.md"};function a(s,t,l,h,g,p){return o(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="sharpspring" tabindex="-1">SharpSpring <a class="header-anchor" href="#sharpspring" aria-label="Permalink to &quot;SharpSpring&quot;">​</a></h1><p>Follow the below steps to connect to the SharpSpring API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select SharpSpring as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-sharpspring-api" tabindex="-1">Step 2. Connect to the SharpSpring API <a class="header-anchor" href="#step-2-connect-to-the-sharpspring-api" aria-label="Permalink to &quot;Step 2. Connect to the SharpSpring API&quot;">​</a></h3><ol><li>Go to <a href="https://sharpspring.com/" target="_blank">SharpSpring</a> and login to your account.</li><li>Click on your profile dropdown on the top-right of the screen, and select <strong>Settings</strong>.</li><li>In the left-hand sidebar menu, click on <strong>API Settings</strong>.</li><li>Click the <strong>Generate New API Keys</strong> button.</li><li>Copy the <strong>Account ID</strong> from SharpSpring and paste in the <strong>Account ID</strong> field in Formie.</li><li>Copy the <strong>Secret Key</strong> from SharpSpring and paste in the <strong>Secret Key</strong> field in Formie.</li></ol><h3 id="step-3-provide-form-base-url" tabindex="-1">Step 3. Provide Form Base URL <a class="header-anchor" href="#step-3-provide-form-base-url" aria-label="Permalink to &quot;Step 3. Provide Form Base URL&quot;">​</a></h3><ol><li>If you do not wish to map Formie Submission to a SharpSpring form, you can skip this step.</li><li>Click <strong>Marketing</strong> &gt; <strong>Content</strong> &gt; <strong>Forms</strong> in SharpSpring&#39;s top toolbar.</li><li>Click the <strong>Create Form</strong> button.</li><li>Enter a name for the form and select the <strong>Native Form</strong> radio button. Click the <strong>Continue</strong> button.</li><li>On the next screen, you&#39;ll be presented with embed instructions. We want to extract two bits of information.</li><li>Seach for the line <code>__ss_noform.push([&#39;baseURI&#39;, &#39;https://app-xxxx.marketingautomation.services/webforms/receivePostback/xxxx/&#39;]);</code></li><li>Copy the <em>just</em> the <strong>URL</strong> value from the embed code (between the single quotes) and paste in the <strong>Form URL</strong> field below.</li></ol><h3 id="step-4-test-connection" tabindex="-1">Step 4. Test Connection <a class="header-anchor" href="#step-4-test-connection" aria-label="Permalink to &quot;Step 4. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-5-form-setting" tabindex="-1">Step 5. Form Setting <a class="header-anchor" href="#step-5-form-setting" aria-label="Permalink to &quot;Step 5. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',12)])])}const m=e(i,[["render",a]]);export{d as __pageData,m as default};
